H = rmedge(G, 1, 2);
numedges(H)
K = rmedge(G, [1 2]);
disp(K.Edges.EndNodes)

G = graph([1 2 3 3 4], [2 3 1 4 5]);
H = rmnode(G, 3);
numnodes(H)
disp(H.Edges.EndNodes)

D = digraph([1 1 2 3 4], [2 3 4 4 5], [1 4 2 1 3]);
T = shortestpathtree(D, 1);
disp(T.Edges)
numedges(T)

G = graph([1 2 4 5 6], [2 3 5 6 4]);
[bins, sizes] = conncomp(G);
[~, k] = max(sizes);
H = subgraph(G, find(bins == k));
numnodes(H)
disp(H.Edges.EndNodes)
